sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        var user = gs.getUser();
        var userName = user.getName();
        var userId = user.getID();

        if (!user || user.getID() === "guest") {
            response.setStatus(401); // Unauthorized
            return { status: "error", message: "User not authenticated" };
        }
        if (!user.hasRole("evt_mgmt_integration")) {
            response.setStatus(403); // Forbidden
            return { status: "error", message: "User not authorized to send events" };
        }
        var body = request.body.data;
        if (!body || !body.event) {
            response.setStatus(400);
            return { status: "error", message: "No event found in payload" };
        }

        var event = body.event;

        //Map severity text to numeric Choice value
        var severityMap = {
            "Critical": 1,
            "Major": 2,
            "Minor": 3,
            "Warning": 4,
            "OK": 5
            };
        var severityValue = severityMap[event.severity];
        // Use provided alertId as message_key
        var messageKey = body.alertId || "default_alertId";

        // Check if an event already exists with same message_key
        var existing = new GlideRecord("em_event");
        existing.addQuery("message_key", messageKey);
        existing.query();
        if (existing.next()) {
            messageKey = existing.message_key.toString();
        }
        var additionalInfo = "";
        if (event.userAgents && Array.isArray(event.userAgents)) {
            additionalInfo = event.userAgents.join(", ");
        }
        // Insert new event
        var gr = new GlideRecord("em_event");
        gr.initialize();
        gr.source = "Cisco Secure Access";
        gr.u_rule_name = event.ruleName || "";
        gr.u_api_key = event.apiKeyId || "";
        gr.description = event.ruleExpression || "";
        gr.additional_info = additionalInfo || "";
        // gr.node = "API Security";
        // gr.type = "API Security";
        // gr.category = "API Threat";
        // gr.event_class = "api.anomaly";
        gr.severity = severityValue;        // Numeric value
        gr.message_key = messageKey;


        var sysId = gr.insert();

        response.setStatus(201);
        return { status: "success", sys_id: sysId, message_key: messageKey, severityValue: severityValue };

    } catch (ex) {
        gs.error("Error creating event: " + ex.message);
        response.setStatus(500);
        return { status: "error", message: ex.message };
    }


})(request, response);
